using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type".
        // Preserve the old property name so existing documents are still readable.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: id format changed from "EntityType|Key" to just the key.
        // Existing docs have ids like "Blog|1". Tell EF Core to keep that format
        // by configuring a custom __id shadow property matching the old convention.
        modelBuilder.Entity<Blog>().Property<string>("__id")
            .HasValueGeneratorFactory<LegacyIdValueGeneratorFactory>()
            .ToJsonProperty("id");

        // Breaking change 3: HasIndex now throws for Cosmos (was silently ignored).
        // Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
    }
}

/// <summary>
/// Reproduces the EF Core 8 id format: "EntityTypeName|KeyValue"
/// so existing Cosmos documents remain accessible.
/// </summary>
class LegacyIdValueGeneratorFactory : ValueGeneratorFactory
{
    public override ValueGenerator Create(
        Microsoft.EntityFrameworkCore.Metadata.IProperty property,
        Microsoft.EntityFrameworkCore.Metadata.ITypeBase typeBase)
        => new LegacyIdValueGenerator();
}

class LegacyIdValueGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    protected override string NextValue(
        Microsoft.EntityFrameworkCore.ChangeTracking.EntityEntry entry)
    {
        var entityType = entry.Metadata.ShortName();
        var key = entry.Property("Id").CurrentValue;
        return $"{entityType}|{key}";
    }
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

